function [tau] = bang_bang_peak_torque(i_max, theta, t_slew)
%BANG_BANG_PEAK_TORQUE  The peak torque of a bang-bang slew: tau = 4 I theta/T^2.
%   i_max: real[kg m^2] (passed in m^2 kg)
%   theta: real[deg] (passed a plain number)
%   t_slew: real[s] (passed in s)
%   returns tau: real[N m] (passed in m^2 kg/s^2)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    tau = 0;
    tau = (((4 * i_max) * theta) / asils.pc.ipow(t_slew, 2));
end
